function doPost(e) {
  var lock = LockService.getScriptLock();
  try {
    // Esperar hasta 15 segundos para evitar escrituras concurrentes que puedan duplicar datos
    lock.waitLock(15000);

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var data = JSON.parse(e.postData.contents);

    // 1. Registro y Guardado del Enlace Webhook y Tasa BCV (Hoja "URL")
    if (data.action === "SYNC_URL" && data.url) {
      var urlSheet = ss.getSheetByName("URL");
      if (!urlSheet) {
        urlSheet = ss.insertSheet("URL");
      }
      urlSheet.clear();

      var now = new Date().toLocaleString();
      var bcv = data.bcvRate ? Number(data.bcvRate) : 54.20;

      var urlRows = [
        ["PARAMETRO", "VALOR", "FECHA_REGISTRO", "DESCRIPCION"],
        ["TASA_BCV", bcv, now, "Tasa Oficial BCV para cálculo de precios en Bolívares (Bs.) en todos los dispositivos"],
        ["URL_WEBHOOK", String(data.url), now, "Enlace de conexión para todos los dispositivos y mesoneros"],
        ["RESTAURANTE", String(data.restaurant || "Restaurante"), now, "Nombre del negocio configurado"],
        ["MONEDA_BASE", String(data.currencySymbol || "$"), now, "Símbolo de moneda base (USD)"],
        ["MONEDA_LOCAL", String(data.currencyBs || "Bs."), now, "Símbolo de moneda local (Bolívares)"],
        ["ESTADO_CONEXION", "Activo y Conectado", now, "El Webhook está respondiendo correctamente a todos los dispositivos"]
      ];

      urlSheet.getRange(1, 1, urlRows.length, urlRows[0].length).setValues(urlRows);
      urlSheet.getRange(1, 1, 1, urlRows[0].length).setFontWeight("bold").setBackground("#e0e7ff");
      urlSheet.autoResizeColumns(1, 4);

      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        url: data.url,
        bcvRate: bcv,
        message: "URL y Tasa BCV registradas en la pestaña URL"
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 2. Sincronización de Menú / Platos (Hoja "Platos") - Reemplazo limpio sin duplicados
    if (data.action === "SYNC_MENU" && data.menu) {
      var menuSheet = ss.getSheetByName("Platos");
      if (!menuSheet) {
        menuSheet = ss.insertSheet("Platos");
      }
      
      // Limpiar completamente contenido y formatos antiguos para evitar duplicar el catálogo
      menuSheet.clear();

      var menuHeaders = [
        "ID_PLATO",
        "NOMBRE",
        "CATEGORIA",
        "PRECIO_USD",
        "DISPONIBLE",
        "DESCRIPCION",
        "ULTIMA_ACTUALIZACION"
      ];

      // Filtrar y desduplicar platos por ID para máxima seguridad
      var seenIds = {};
      var uniqueMenu = [];
      data.menu.forEach(function(m) {
        var idKey = String(m.id || m.name);
        if (!seenIds[idKey]) {
          seenIds[idKey] = true;
          uniqueMenu.push(m);
        }
      });

      var nowStr = new Date().toLocaleString();
      var menuRows = [menuHeaders];

      uniqueMenu.forEach(function(m) {
        menuRows.push([
          String(m.id || ""),
          String(m.name || ""),
          String(m.category || "General"),
          Number(m.price) || 0,
          m.available !== false ? "Disponible" : "Agotado",
          String(m.description || ""),
          nowStr
        ]);
      });

      // Escribir exactamente desde A1 en un solo bloque (setValues)
      menuSheet.getRange(1, 1, menuRows.length, menuRows[0].length).setValues(menuRows);
      menuSheet.getRange(1, 1, 1, menuRows[0].length).setFontWeight("bold").setBackground("#fef3c7");
      menuSheet.autoResizeColumns(1, 7);

      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        count: uniqueMenu.length,
        message: "Catálogo de platos sincronizado sin duplicados"
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 3. Sincronización de Mesas y Estado de Ocupación (Hoja "Mesas")
    if (data.action === "SYNC_TABLES" && data.tables) {
      var tableSheet = ss.getSheetByName("Mesas");
      if (!tableSheet) {
        tableSheet = ss.insertSheet("Mesas");
      }
      tableSheet.clear();

      var tableHeaders = [
        "ID_MESA",
        "NOMBRE_MESA",
        "CAPACIDAD",
        "ZONA",
        "ESTADO",
        "PEDIDO_ACTIVO",
        "MESONERO_ASIGNADO",
        "TOTAL_ACTUAL",
        "CANTIDAD_PLATOS",
        "ULTIMA_ACTUALIZACION"
      ];

      var nowTable = new Date().toLocaleString();
      var tableRows = [tableHeaders];

      data.tables.forEach(function(t) {
        tableRows.push([
          String(t.id || ""),
          String(t.name || ""),
          Number(t.capacity) || 4,
          String(t.zone || "Principal"),
          String(t.status || "libre"),
          String(t.activeOrderNumber || "Ninguno"),
          String(t.waiterName || "N/A"),
          Number(t.total) || 0,
          Number(t.itemCount) || 0,
          nowTable
        ]);
      });

      tableSheet.getRange(1, 1, tableRows.length, tableRows[0].length).setValues(tableRows);
      tableSheet.getRange(1, 1, 1, tableRows[0].length).setFontWeight("bold").setBackground("#dcfce7");
      tableSheet.autoResizeColumns(1, 10);

      return ContentService.createTextOutput(JSON.stringify({ status: "success", count: data.tables.length }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    // 4. Sincronización de Usuarios (Hoja "Usuario")
    if (data.action === "SYNC_USERS" && data.users) {
      var userSheet = ss.getSheetByName("Usuario");
      if (!userSheet) {
        userSheet = ss.insertSheet("Usuario");
      }
      userSheet.clear();

      var userHeaders = [
        "ID_USUARIO",
        "NOMBRE_USUARIO",
        "ROL",
        "PIN",
        "ESTADO",
        "FECHA_CREACION"
      ];

      var userRows = [userHeaders];
      data.users.forEach(function(u) {
        userRows.push([
          String(u.id || ""),
          String(u.name || ""),
          String(u.role || ""),
          String(u.pin || ""),
          u.active ? "Activo" : "Inactivo",
          String(u.createdAt || "")
        ]);
      });

      userSheet.getRange(1, 1, userRows.length, userRows[0].length).setValues(userRows);
      userSheet.getRange(1, 1, 1, userRows[0].length).setFontWeight("bold").setBackground("#e2e8f0");
      userSheet.autoResizeColumns(1, 6);

      return ContentService.createTextOutput(JSON.stringify({ status: "success", count: data.users.length }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    // 5. Hoja de Ventas / Comandas
    var sheet = ss.getSheetByName("Ventas");
    if (!sheet) {
      var defaultSheet = ss.getSheetByName("Hoja 1") || ss.getSheetByName("Sheet1");
      if (defaultSheet) {
        defaultSheet.setName("Ventas");
        sheet = defaultSheet;
      } else {
        sheet = ss.insertSheet("Ventas");
      }
    }

    // Si la hoja está vacía, agregar encabezados
    if (sheet.getLastRow() === 0) {
      sheet.appendRow([
        "FECHA_PAGO",
        "NUMERO_PEDIDO",
        "MESA",
        "MESONERO",
        "SUBTOTAL",
        "IMPUESTOS",
        "PROPINA",
        "TOTAL",
        "METODO_PAGO",
        "REFERENCIA",
        "ITEMS_CONSUMIDOS"
      ]);
      sheet.getRange("A1:K1").setFontWeight("bold").setBackground("#e2e8f0");
    }

    if (data.action === "ADD_ORDER") {
      sheet.appendRow([
        data.paidAt,
        data.orderNumber,
        data.tableName,
        data.waiterName,
        data.subtotal,
        data.taxAmount,
        data.tipAmount,
        data.total,
        data.paymentMethod,
        data.paymentReference || "",
        data.items
      ]);
      return ContentService.createTextOutput(JSON.stringify({ status: "success" }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    if (data.action === "SYNC_ALL" && data.orders) {
      var existingOrders = {};
      if (sheet.getLastRow() > 1) {
        var orderCol = sheet.getRange(2, 2, sheet.getLastRow() - 1, 1).getValues();
        orderCol.forEach(function(row) {
          if (row[0]) existingOrders[String(row[0])] = true;
        });
      }
      data.orders.forEach(function(o) {
        if (!existingOrders[String(o.orderNumber)]) {
          sheet.appendRow([
            o.paidAt,
            o.orderNumber,
            o.tableName,
            o.waiterName,
            o.subtotal,
            o.taxAmount,
            o.tipAmount,
            o.total,
            o.paymentMethod,
            "",
            o.items
          ]);
        }
      });
      return ContentService.createTextOutput(JSON.stringify({ status: "success", count: data.orders.length }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    return ContentService.createTextOutput(JSON.stringify({ status: "received" }))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ error: error.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    try {
      lock.releaseLock();
    } catch(e) {}
  }
}

function doGet(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var action = (e && e.parameter && e.parameter.action) || "";

    // 1. OBTENER TODO EN 1 SOLA LLAMADA (Para sincronización ultra-rápida de nuevos dispositivos)
    if (action === "GET_ALL") {
      var cfg = getGasConfig(ss);
      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        bcvRate: cfg.bcvRate,
        url: cfg.url,
        restaurant: cfg.restaurant,
        config: cfg.config,
        menu: getGasMenu(ss),
        tables: getGasTables(ss),
        users: getGasUsers(ss),
        orders: getGasSales(ss)
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 2. OBTENER VENTAS / COMANDAS HISTÓRICAS
    if (action === "GET_VENTAS" || action === "GET_ORDERS" || action === "GET_SALES") {
      var salesList = getGasSales(ss);
      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        count: salesList.length,
        orders: salesList
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 3. OBTENER USUARIOS Y MESONEROS
    if (action === "GET_USERS") {
      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        users: getGasUsers(ss)
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 4. OBTENER CATÁLOGO DE PLATOS / MENÚ
    if (action === "GET_MENU") {
      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        menu: getGasMenu(ss)
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 5. OBTENER MESAS Y CAPACIDAD
    if (action === "GET_TABLES") {
      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        tables: getGasTables(ss)
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // 6. OBTENER TASA BCV Y PARÁMETROS
    if (action === "GET_BCV" || action === "GET_CONFIG" || action === "GET_URL") {
      var cfgOnly = getGasConfig(ss);
      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        bcvRate: cfgOnly.bcvRate,
        url: cfgOnly.url,
        restaurant: cfgOnly.restaurant,
        config: cfgOnly.config
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // Respuesta por defecto
    var defaultCfg = getGasConfig(ss);
    return ContentService.createTextOutput(JSON.stringify({
      status: "online",
      message: "Webhook de Restaurant POS activo",
      bcvRate: defaultCfg.bcvRate
    })).setMimeType(ContentService.MimeType.JSON);

  } catch(err) {
    return ContentService.createTextOutput(JSON.stringify({ error: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

// FUNCIONES AUXILIARES PARA LECTURA DE HOJAS
function cleanGasNumber(val) {
  if (val === undefined || val === null || val === '') return 0;
  if (typeof val === 'number') return isNaN(val) ? 0 : val;
  var str = String(val).replace(/[$€Bss]/gi, '').trim();
  if (str.indexOf(',') !== -1 && str.indexOf('.') !== -1) {
    if (str.indexOf(',') < str.indexOf('.')) {
      str = str.replace(/,/g, '');
    } else {
      str = str.replace(/./g, '').replace(',', '.');
    }
  } else if (str.indexOf(',') !== -1) {
    str = str.replace(',', '.');
  }
  var n = parseFloat(str);
  return isNaN(n) ? 0 : n;
}

function cleanOrderNumber(val, defaultNum) {
  if (val === undefined || val === null || val === '') return defaultNum;
  var str = String(val).trim();
  var match = str.match(/d+/);
  if (match) {
    var n = parseInt(match[0], 10);
    return isNaN(n) ? defaultNum : n;
  }
  return defaultNum;
}

function cleanGasDate(val) {
  if (!val) return new Date().toISOString();
  if (val instanceof Date) {
    return isNaN(val.getTime()) ? new Date().toISOString() : val.toISOString();
  }
  var str = String(val).trim();
  var parsed = new Date(str);
  if (!isNaN(parsed.getTime())) return parsed.toISOString();
  return str || new Date().toISOString();
}

function getGasConfig(ss) {
  var urlSheet = ss.getSheetByName("URL");
  var config = {};
  var bcvRate = null;
  if (urlSheet && urlSheet.getLastRow() > 1) {
    var lastCol = Math.min(2, urlSheet.getLastColumn());
    var data = urlSheet.getRange(2, 1, urlSheet.getLastRow() - 1, lastCol).getValues();
    data.forEach(function(r) {
      if (r[0]) {
        config[String(r[0])] = r[1];
        if (String(r[0]) === "TASA_BCV") bcvRate = cleanGasNumber(r[1]);
      }
    });
  }
  return {
    config: config,
    bcvRate: bcvRate,
    url: config["URL_WEBHOOK"] || "",
    restaurant: config["RESTAURANTE"] || ""
  };
}

function getGasMenu(ss) {
  var menuSheet = ss.getSheetByName("Platos") || ss.getSheetByName("Menu") || ss.getSheetByName("Menú") || ss.getSheetByName("Dishes") || ss.getSheetByName("Carta");
  var items = [];
  if (menuSheet && menuSheet.getLastRow() > 1) {
    var mCols = menuSheet.getLastColumn();
    if (mCols < 1) return [];
    var mData = menuSheet.getRange(2, 1, menuSheet.getLastRow() - 1, mCols).getValues();
    var mHeaders = menuSheet.getRange(1, 1, 1, mCols).getValues()[0];
    var cId = 0, cName = 1, cCat = 2, cPrice = 3, cAvail = 4, cDesc = 5;
    for (var mi = 0; mi < mHeaders.length; mi++) {
      var mh = String(mHeaders[mi] || "").toLowerCase().trim();
      if (mh.indexOf("id") !== -1 || mh.indexOf("codigo") !== -1) cId = mi;
      else if (mh.indexOf("nombre") !== -1 || mh.indexOf("plato") !== -1) cName = mi;
      else if (mh.indexOf("categoria") !== -1 || mh.indexOf("categoría") !== -1 || mh.indexOf("rubro") !== -1) cCat = mi;
      else if (mh.indexOf("precio") !== -1 || mh.indexOf("price") !== -1) cPrice = mi;
      else if (mh.indexOf("disponible") !== -1 || mh.indexOf("estado") !== -1 || mh.indexOf("activo") !== -1) cAvail = mi;
      else if (mh.indexOf("descripcion") !== -1 || mh.indexOf("descripción") !== -1) cDesc = mi;
    }

    items = mData.filter(function(r) {
      return r && r[cName] && String(r[cName]).trim() !== "";
    }).map(function(r) {
      var avStr = String(r[cAvail] !== undefined && r[cAvail] !== null ? r[cAvail] : "").trim().toLowerCase();
      var isAvail = avStr === "" || avStr === "disponible" || avStr === "activo" || avStr === "true" || avStr === "si" || avStr === "sí" || avStr === "1";
      return {
        id: String(r[cId] || "").trim(),
        name: String(r[cName] || "").trim(),
        category: String(r[cCat] || "General").trim(),
        price: cleanGasNumber(r[cPrice]),
        available: isAvail,
        description: String(r[cDesc] || "").trim()
      };
    });
  }
  return items;
}

function getGasTables(ss) {
  var tableSheet = ss.getSheetByName("Mesas") || ss.getSheetByName("Mesa") || ss.getSheetByName("Tables");
  var tables = [];
  if (tableSheet && tableSheet.getLastRow() > 1) {
    var tCols = tableSheet.getLastColumn();
    if (tCols < 1) return [];
    var tData = tableSheet.getRange(2, 1, tableSheet.getLastRow() - 1, tCols).getValues();
    var tHeaders = tableSheet.getRange(1, 1, 1, tCols).getValues()[0];
    var tcId = 0, tcName = 1, tcCap = 2, tcZone = 3, tcStat = 4;
    for (var ti = 0; ti < tHeaders.length; ti++) {
      var th = String(tHeaders[ti] || "").toLowerCase().trim();
      if (th.indexOf("id") !== -1 || th.indexOf("codigo") !== -1) tcId = ti;
      else if (th.indexOf("nombre") !== -1 || th.indexOf("mesa") !== -1) tcName = ti;
      else if (th.indexOf("capacidad") !== -1 || th.indexOf("personas") !== -1) tcCap = ti;
      else if (th.indexOf("zona") !== -1 || th.indexOf("area") !== -1) tcZone = ti;
      else if (th.indexOf("estado") !== -1 || th.indexOf("status") !== -1) tcStat = ti;
    }

    tables = tData.filter(function(r) {
      return r && r[tcName] && String(r[tcName]).trim() !== "";
    }).map(function(r, idx) {
      return {
        id: String(r[tcId] || "t_" + (idx + 1)).trim(),
        name: String(r[tcName] || "").trim(),
        capacity: Number(r[tcCap]) || 4,
        zone: String(r[tcZone] || "Salón Principal").trim(),
        status: String(r[tcStat] || "libre").trim().toLowerCase()
      };
    });
  }
  return tables;
}

function getGasUsers(ss) {
  var userSheet = ss.getSheetByName("Usuario") || 
                  ss.getSheetByName("Usuarios") || 
                  ss.getSheetByName("Users") || 
                  ss.getSheetByName("Personal") || 
                  ss.getSheetByName("Mesoneros");
  if (!userSheet) {
    var allSheets = ss.getSheets();
    for (var s = 0; s < allSheets.length; s++) {
      var sName = allSheets[s].getName().toLowerCase().trim();
      if (sName.indexOf("usuario") !== -1 || sName.indexOf("user") !== -1 || sName.indexOf("personal") !== -1 || sName.indexOf("mesonero") !== -1) {
        userSheet = allSheets[s];
        break;
      }
    }
  }

  var users = [];
  if (userSheet && userSheet.getLastRow() >= 1) {
    var uCols = userSheet.getLastColumn();
    if (uCols < 1) return [];
    var allData = userSheet.getRange(1, 1, userSheet.getLastRow(), uCols).getValues();
    if (allData.length > 0) {
      var uHeaders = allData[0];
      var hasHeaders = false;
      var ucId = 0, ucName = 1, ucRole = 2, ucPin = 3, ucActive = 4;
      for (var ui = 0; ui < uHeaders.length; ui++) {
        var uh = String(uHeaders[ui] || "").toLowerCase().trim();
        if (uh.indexOf("id") !== -1 || uh.indexOf("codigo") !== -1 || uh.indexOf("numero") !== -1) { ucId = ui; hasHeaders = true; }
        else if (uh.indexOf("nombre") !== -1 || uh.indexOf("name") !== -1 || uh.indexOf("mesonero") !== -1 || uh.indexOf("usuario") !== -1) { ucName = ui; hasHeaders = true; }
        else if (uh.indexOf("rol") !== -1 || uh.indexOf("role") !== -1 || uh.indexOf("cargo") !== -1 || uh.indexOf("tipo") !== -1) { ucRole = ui; hasHeaders = true; }
        else if (uh.indexOf("pin") !== -1 || uh.indexOf("clave") !== -1 || uh.indexOf("pass") !== -1) { ucPin = ui; hasHeaders = true; }
        else if (uh.indexOf("estado") !== -1 || uh.indexOf("status") !== -1 || uh.indexOf("activo") !== -1) { ucActive = ui; hasHeaders = true; }
      }

      var startIdx = (hasHeaders && allData.length > 1) ? 1 : 0;
      for (var rowIdx = startIdx; rowIdx < allData.length; rowIdx++) {
        var r = allData[rowIdx];
        if (!r) continue;
        var rawName = String(r[ucName] !== undefined && r[ucName] !== null ? r[ucName] : "").trim();
        if (!rawName && r[0] && isNaN(Number(r[0]))) rawName = String(r[0]).trim();
        if (!rawName || rawName.toLowerCase() === "nombre" || rawName.toLowerCase() === "name") continue;

        var actVal = String(r[ucActive] !== undefined && r[ucActive] !== null ? r[ucActive] : "").trim().toLowerCase();
        var isActive = actVal === "" || actVal === "activo" || actVal === "activa" || actVal === "true" || actVal === "si" || actVal === "sí" || actVal === "1";
        
        var rawR = String(r[ucRole] || "").trim().toLowerCase();
        var role = "mesonero";
        if (rawR.indexOf("admin") !== -1 || rawR.indexOf("gerente") !== -1 || rawR.indexOf("encargad") !== -1 || rawR.indexOf("dueñ") !== -1 || rawR.indexOf("duen") !== -1) {
          role = "admin";
        } else if (rawR.indexOf("cocin") !== -1 || rawR.indexOf("chef") !== -1) {
          role = "cocina";
        }

        var pinStr = String(r[ucPin] !== undefined && r[ucPin] !== null ? r[ucPin] : "").trim();

        users.push({
          id: Number(r[ucId]) || (users.length + 1),
          name: rawName,
          role: role,
          pin: pinStr || "1234",
          active: isActive
        });
      }
    }
  }
  return users;
}

function getGasSales(ss) {
  try {
    var sheet = ss.getSheetByName("Ventas") || ss.getSheetByName("Venta") || ss.getSheetByName("Orders") || ss.getSheetByName("Comandas");
    if (!sheet) {
      var allSheets = ss.getSheets();
      for (var s = 0; s < allSheets.length; s++) {
        var sName = allSheets[s].getName().toLowerCase().trim();
        if (sName.indexOf("venta") !== -1 || sName.indexOf("order") !== -1 || sName.indexOf("comanda") !== -1 || sName.indexOf("factur") !== -1 || sName.indexOf("cobro") !== -1) {
          sheet = allSheets[s];
          break;
        }
      }
    }

    // Fallback: si no se encontró por nombre, buscar si la primera hoja contiene ventas
    if (!sheet) {
      var firstSheet = ss.getSheets()[0];
      if (firstSheet) {
        var fName = firstSheet.getName().toLowerCase();
        if (fName.indexOf("plato") === -1 && fName.indexOf("mesa") === -1 && fName.indexOf("usuario") === -1 && fName.indexOf("url") === -1) {
          sheet = firstSheet;
        }
      }
    }

    var orders = [];
    if (sheet && sheet.getLastRow() > 1) {
      var lastCol = sheet.getLastColumn();
      if (lastCol < 1) return [];
      var lastRow = sheet.getLastRow();

      var allData = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
      var headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0];

      var cDate = -1, cNum = -1, cTable = -1, cWaiter = -1, cSub = -1, cTax = -1, cTip = -1, cTot = -1, cMethod = -1, cRef = -1, cItems = -1;
      for (var hi = 0; hi < headers.length; hi++) {
        var h = String(headers[hi] || "").toLowerCase().trim();
        if (h.indexOf("fecha") !== -1 || h.indexOf("date") !== -1 || h.indexOf("hora") !== -1 || h.indexOf("paid") !== -1) cDate = hi;
        else if (h.indexOf("pedido") !== -1 || h.indexOf("order") !== -1 || h.indexOf("numero") !== -1 || h.indexOf("número") !== -1 || h.indexOf("num") !== -1 || h.indexOf("#") !== -1 || h.indexOf("id") !== -1) cNum = hi;
        else if (h.indexOf("mesa") !== -1 || h.indexOf("table") !== -1) cTable = hi;
        else if (h.indexOf("mesonero") !== -1 || h.indexOf("waiter") !== -1 || h.indexOf("mozo") !== -1 || h.indexOf("mesero") !== -1 || h.indexOf("atendido") !== -1) cWaiter = hi;
        else if (h.indexOf("subtotal") !== -1 || h.indexOf("sub-total") !== -1 || h.indexOf("sub total") !== -1) cSub = hi;
        else if (h.indexOf("impuesto") !== -1 || h.indexOf("tax") !== -1 || h.indexOf("iva") !== -1) cTax = hi;
        else if (h.indexOf("propina") !== -1 || h.indexOf("tip") !== -1) cTip = hi;
        else if (h.indexOf("total") !== -1 || h.indexOf("monto") !== -1 || h.indexOf("importe") !== -1 || h.indexOf("precio") !== -1 || h.indexOf("valor") !== -1) cTot = hi;
        else if (h.indexOf("metodo") !== -1 || h.indexOf("método") !== -1 || h.indexOf("payment") !== -1 || h.indexOf("forma") !== -1 || h.indexOf("pago") !== -1) cMethod = hi;
        else if (h.indexOf("referencia") !== -1 || h.indexOf("ref") !== -1 || h.indexOf("comprobante") !== -1) cRef = hi;
        else if (h.indexOf("item") !== -1 || h.indexOf("consumo") !== -1 || h.indexOf("plato") !== -1 || h.indexOf("producto") !== -1 || h.indexOf("detalle") !== -1 || h.indexOf("descripcion") !== -1) cItems = hi;
      }

      // Índices por defecto si no tienen encabezados reconocibles
      if (cDate === -1) cDate = 0;
      if (cNum === -1) cNum = Math.min(1, lastCol - 1);
      if (cTable === -1) cTable = Math.min(2, lastCol - 1);
      if (cWaiter === -1) cWaiter = Math.min(3, lastCol - 1);
      if (cSub === -1) cSub = Math.min(4, lastCol - 1);
      if (cTot === -1) cTot = (lastCol > 7) ? 7 : Math.max(0, lastCol - 1);

      for (var idx = 0; idx < allData.length; idx++) {
        var r = allData[idx];
        if (!r || r.length === 0) continue;

        var orderNum = cleanOrderNumber(cNum >= 0 ? r[cNum] : null, idx + 101);
        var total = cleanGasNumber(cTot >= 0 ? r[cTot] : 0);
        var subtotal = cleanGasNumber(cSub >= 0 ? r[cSub] : 0) || total;
        var tax = cleanGasNumber(cTax >= 0 ? r[cTax] : 0);
        var tip = cleanGasNumber(cTip >= 0 ? r[cTip] : 0);
        var tableName = (cTable >= 0 && r[cTable]) ? String(r[cTable]).trim() : "Mesa 1";
        var waiterName = (cWaiter >= 0 && r[cWaiter]) ? String(r[cWaiter]).trim() : "Mesonero";
        var method = (cMethod >= 0 && r[cMethod]) ? String(r[cMethod]).trim().toLowerCase() : "efectivo";
        var ref = (cRef >= 0 && r[cRef]) ? String(r[cRef]).trim() : "";
        var items = (cItems >= 0 && r[cItems]) ? String(r[cItems]).trim() : "";
        var paidAt = cleanGasDate(cDate >= 0 ? r[cDate] : null);

        if (total > 0 || subtotal > 0 || items.length > 0 || (cNum >= 0 && String(r[cNum] || "").trim().length > 0)) {
          orders.push({
            orderNumber: orderNum,
            tableName: tableName || "Mesa 1",
            waiterName: waiterName || "Mesonero",
            subtotal: subtotal,
            taxAmount: tax,
            tipAmount: tip,
            total: total > 0 ? total : subtotal,
            paymentMethod: method || "efectivo",
            paymentReference: ref,
            items: items,
            paidAt: paidAt
          });
        }
      }
    }
    return orders;
  } catch(e) {
    return [];
  }
}
